/*
 * FINISH A STEP, AND OPEN THE NEXT ONE (TASK-L178).
 *
 * The product's `completeStep` does two writes in one TRANSACTION: this step
 * `complete`, the next `available`. NodeGX has no transaction a function can
 * reach — HLT-016 (b) is ruled out until a real case needs it — so this is
 * three single-row writes, each guarded on what was read, in an ORDER chosen so
 * that every state a crash between two of them can leave is one the learner's
 * own next action heals (TASK-L178 §3 is the measurement; its Status records
 * every partial state). The order:
 *
 *   1. stamp their progress row — invisible until the step is complete, because
 *      a lesson entry's moment is that row's stamp ONLY on a complete step (L116);
 *   2. open the next step, only if it is still `locked`;
 *   3. complete this step, only if it is still what was read.
 *
 * A crash after 1 changes nothing they can see. A crash after 2 leaves the next
 * step open AND this one still theirs to finish — two open steps, which is what
 * they see on any day they have not finished one yet, and pressing Mark complete
 * again finishes it. The other order (complete, then open) can leave every step
 * done and nothing open.
 *
 * A 409 on a step is READ AGAIN: if the row now holds what this was writing,
 * somebody else got there first (a double press, a second tab) and that is
 * success. Otherwise it is tried again, at most 4 times. Never a 200 while a
 * write is unresolved.
 *
 * `findStepToUnlock` is the product's, ported verbatim: the first locked step
 * whose every earlier step is complete, counting this one as complete. The walk
 * is over LIVE steps only (L113): a removed step is never what a step unlocks
 * into.
 *
 * IDENTITY COMES FROM THE SESSION. The answer is the product's: every live step
 * with its status, in position order.
 */
if (Inputs.learnerId !== undefined && Inputs.conceptId !== undefined) {
  (async () => {
    const refuse = (why) => {
      Outputs.error = why;
      console.error('[dbt:finishStep] refused: ' + why + ' learner=' + String(Inputs.learnerId || '-'));
      Outputs.failed();
    };
    try {
      const q = (c, where, limit) => Noodl.Records.query(c, where, { limit: limit || 1000, plain: true });
      const learnerId = String(Inputs.learnerId || '');
      const conceptId = String(Inputs.conceptId || '');
      if (!learnerId) return refuse('no learner');
      if (!conceptId) return refuse('no concept');

      const paths = await q('LearningPath', { learnerId: { equalTo: learnerId } });
      const live = [...paths].sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1))[0];
      if (!live) return refuse('no path');
      const liveSteps = async () =>
        (await q('PathStep', { pathId: { equalTo: live.pathId } }))
          .filter((s) => s.removedAt === undefined || s.removedAt === null)
          .sort((a, b) => a.position - b.position);

      let steps = await liveSteps();
      const target = steps.find((s) => s.conceptId === conceptId);
      if (!target || target.status === 'locked') return refuse('step not open');

      /* The product's findStepToUnlock (src/lib/server/delivery/service.ts), verbatim. */
      function findStepToUnlock(allSteps, justCompletedConceptId) {
        const completedIds = new Set(
          allSteps
            .filter((s) => s.status === 'complete' || s.conceptId === justCompletedConceptId)
            .map((s) => s.conceptId)
        );
        for (const step of allSteps) {
          if (step.status !== 'locked') continue;
          const priorSteps = allSteps.filter((s) => s.position < step.position);
          const allPriorComplete = priorSteps.every((s) => completedIds.has(s.conceptId));
          if (allPriorComplete) return step.conceptId;
        }
        return null;
      }

      /* One step row to `want`, only if it still holds `from`. A conflict is read
         again: already `want` is success; anything else is tried again. */
      async function setStatus(conceptOf, from, want) {
        for (let attempt = 1; attempt <= 4; attempt++) {
          const row = (await liveSteps()).find((s) => s.conceptId === conceptOf);
          if (!row) throw new Error('step vanished: ' + conceptOf);
          if (row.status === want) return;
          if (from !== null && row.status !== from) throw new Error('step ' + conceptOf + ' is ' + row.status + ', not ' + from);
          try {
            await Noodl.Records.save(row.objectId, { status: want }, { className: 'PathStep', ifMatch: { status: row.status } });
            return;
          } catch (e) {
            if (!e || e.code !== 'precondition-failed') throw e;
            console.warn('[dbt:finishStep] conflict learner=' + learnerId + ' step=' + conceptOf + ' attempt=' + attempt);
            await new Promise((r) => setTimeout(r, 5 + Math.floor(Math.random() * 25)));
          }
        }
        throw new Error('still conflicting on ' + conceptOf);
      }

      // 1. Stamp their progress row. Last writer wins on a timestamp, which is right:
      //    two presses a second apart finished the step at about the same moment.
      const now = new Date().toISOString();
      const progress = await q('Progress', { and: [{ learnerId: { equalTo: learnerId } }, { conceptId: { equalTo: conceptId } }] }, 2);
      if (progress.length) {
        await Noodl.Records.save(progress[0].objectId, { completedAt: now }, { className: 'Progress' });
      } else {
        try {
          await Noodl.Records.create('Progress', { learnerId, conceptId, completedAt: now, reachedWowMoment: false });
        } catch (e) {
          // (learnerId, conceptId) is unique: a concurrent finish created it first. Stamp that one.
          const again = await q('Progress', { and: [{ learnerId: { equalTo: learnerId } }, { conceptId: { equalTo: conceptId } }] }, 2);
          if (!again.length) throw e;
          await Noodl.Records.save(again[0].objectId, { completedAt: now }, { className: 'Progress' });
        }
      }

      // 2. Open the next step, only if it is still locked.
      const next = findStepToUnlock(steps, conceptId);
      if (next) await setStatus(next, 'locked', 'available');

      // 3. Complete this one, only if it is still what was read.
      await setStatus(conceptId, null, 'complete');

      steps = await liveSteps();
      Outputs.steps = steps.map((s) => ({ conceptId: s.conceptId, status: s.status }));
      Outputs.done();
    } catch (e) {
      refuse(String((e && e.message) || e));
    }
  })();
}
